// Normalise four different API shapes into one schema.
// Defensive by design: a source returning garbage must never kill the run.
const MAX_DESC = 4000;

const text = (v) => (v === null || v === undefined ? '' : String(v));
const strip = (s) =>
  text(s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

// Some feeds double-encode UTF-8 (an en dash arrives as "a-hat + control chars").
// Repair only when the result is unambiguous, so real text is never mangled.
function fixMojibake(s) {
  if (!/[\u00C2\u00C3\u00E2][\u0080-\u00BF]/.test(s)) return s;
  try {
    const repaired = Buffer.from(s, 'latin1').toString('utf8');
    if (!repaired.includes('\uFFFD') && !/[\u00C2\u00C3\u00E2][\u0080-\u00BF]/.test(repaired)) return repaired;
  } catch (e) {
    /* not repairable - keep the original */
  }
  return s;
}

const clean = (s) => fixMojibake(strip(s));

function fingerprint(company, title, location) {
  const norm = (v) =>
    text(v)
      .toLowerCase()
      .replace(/\b(inc|llc|ltd|pvt|private|limited|corp|corporation|technologies|solutions|labs|gmbh)\b/g, '')
      .replace(/[^a-z0-9]+/g, ' ')
      .trim();
  const base = [norm(company), norm(title), norm(location)].join('|');
  try {
    const crypto = require('crypto');
    return crypto.createHash('sha256').update(base).digest('hex').slice(0, 32);
  } catch (e) {
    // Fallback so the workflow still runs in a hardened sandbox.
    let h = 2166136261;
    for (let i = 0; i < base.length; i++) {
      h ^= base.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return 'fnv' + (h >>> 0).toString(16) + base.length;
  }
}

const tagsOf = (t) => {
  const arr = Array.isArray(t) ? t : [];
  return arr
    .map((x) => clean(typeof x === 'string' ? x : (x && (x.name || x.label)) || ''))
    .filter(Boolean)
    .slice(0, 12);
};

const ts = (v) => {
  if (!v) return null;
  const d = new Date(typeof v === 'number' ? v * 1000 : v);
  return isNaN(d.getTime()) ? null : d.toISOString();
};

// Coarse country/region tag so you can filter "show me Germany" with one WHERE.
// First match wins, so city names beat generic words like "Remote".
const COUNTRY_HINTS = [
  ['de', /germany|deutschland|berlin|munich|münchen|munchen|hamburg|frankfurt|cologne|köln|koln|stuttgart|düsseldorf|dusseldorf|leipzig|dresden/],
  ['at', /austria|österreich|osterreich|vienna|wien|graz|linz/],
  ['ch', /switzerland|schweiz|zurich|zürich|geneva|genf|basel|lausanne/],
  ['nl', /netherlands|nederland|amsterdam|rotterdam|utrecht|eindhoven|the hague/],
  ['fr', /france|paris|lyon|toulouse|nantes|bordeaux|lille/],
  ['es', /spain|españa|espana|madrid|barcelona|valencia|seville/],
  ['it', /italy|italia|milan|milano|rome|roma|turin|torino|bologna/],
  ['pl', /poland|polska|warsaw|warszawa|krakow|kraków|wroclaw|gdańsk|gdansk/],
  ['ie', /ireland|dublin|cork|galway/],
  ['gb', /united kingdom|great britain|england|scotland|wales|london|manchester|edinburgh|birmingham|leeds|bristol|glasgow/],
  ['se', /sweden|stockholm|gothenburg|malmö|malmo/],
  ['dk', /denmark|copenhagen|aarhus/],
  ['no', /norway|oslo|bergen/],
  ['fi', /finland|helsinki|espoo/],
  ['pt', /portugal|lisbon|lisboa|porto/],
  ['cz', /czech|prague|praha|brno/],
  ['ro', /romania|bucharest|cluj/],
  ['ca', /canada|toronto|vancouver|montreal|ottawa|calgary/],
  ['us', /united states|\busa\b|u\.s\.|new york|san francisco|seattle|austin|boston|chicago|denver|atlanta/],
  ['in', /india|bangalore|bengaluru|hyderabad|pune|chennai|mumbai|delhi|noida|gurgaon|gurugram|ahmedabad|kolkata/],
  ['au', /australia|sydney|melbourne|brisbane|perth/],
  ['sg', /singapore/],
  ['ae', /dubai|abu dhabi|\buae\b/],
  ['jp', /japan|tokyo|osaka/],
];

function countryFor(location) {
  const s = text(location).toLowerCase();
  if (!s) return null;
  for (const [code, re] of COUNTRY_HINTS) if (re.test(s)) return code;
  if (/worldwide|anywhere|global/.test(s)) return 'remote';
  if (/remote/.test(s)) return 'remote';
  return null;
}

const out = [];
const seen = new Set();

function push(row) {
  if (!row.title || !row.company) return;
  const fp = fingerprint(row.company, row.title, row.location);
  if (seen.has(fp)) return;
  seen.add(fp);
  out.push({
    ...row,
    country: row.country !== undefined ? row.country : countryFor(row.location),
    fingerprint: fp,
    description: clean(row.description).slice(0, MAX_DESC),
    tags: tagsOf(row.tags),
    posted_at: ts(row.posted_at),
  });
}

for (const item of $input.all()) {
  const j = item.json || {};

  // Jobicy: { jobs: [...] } with jobTitle / companyName keys
  if (Array.isArray(j.jobs) && j.jobs[0] && j.jobs[0].jobTitle !== undefined) {
    for (const r of j.jobs) {
      push({
        source: 'jobicy',
        external_id: text(r.id),
        title: clean(r.jobTitle),
        company: clean(r.companyName),
        location: clean(r.jobGeo) || 'Remote',
        url: text(r.url),
        description: r.jobDescription,
        tags: [].concat(r.jobIndustry || [], r.jobType || [], r.jobLevel ? [r.jobLevel] : []),
        posted_at: r.pubDate,
        salary_text: r.annualSalaryMin
          ? text(r.annualSalaryMin) + '-' + text(r.annualSalaryMax) + ' ' + text(r.annualSalaryCurrency)
          : '',
      });
    }
    continue;
  }

  // Remotive: { jobs: [...] }
  if (Array.isArray(j.jobs)) {
    for (const r of j.jobs) {
      push({
        source: 'remotive',
        external_id: text(r.id),
        title: clean(r.title),
        company: clean(r.company_name),
        location: clean(r.candidate_required_location) || 'Remote',
        url: text(r.url),
        description: r.description,
        tags: r.tags,
        posted_at: r.publication_date,
        salary_text: clean(r.salary),
      });
    }
    continue;
  }

  // Arbeitnow: { data: [...] }
  if (Array.isArray(j.data)) {
    for (const r of j.data) {
      push({
        source: 'arbeitnow',
        external_id: text(r.slug || r.url),
        title: clean(r.title),
        company: clean(r.company_name),
        location: clean(r.location) || (r.remote ? 'Remote' : ''),
        url: text(r.url),
        description: r.description,
        tags: r.tags,
        posted_at: r.created_at,
        salary_text: '',
      });
    }
    continue;
  }

  // RemoteOK: array response, sometimes exploded into one item per job.
  const arr = Array.isArray(j) ? j : j && j.position && j.id ? [j] : [];
  for (const r of arr) {
    if (!r || !r.id || !r.position) continue; // skips the legal notice row
    push({
      source: 'remoteok',
      external_id: text(r.id),
      title: clean(r.position),
      company: clean(r.company),
      location: clean(r.location) || 'Remote',
      url: text(r.url) || 'https://remoteok.com/remote-jobs/' + text(r.slug),
      description: r.description,
      tags: r.tags,
      posted_at: r.date,
      salary_text: r.salary_min ? text(r.salary_min) : '',
    });
  }
}

if (!out.length) {
  return [{ json: { empty: true, note: 'no parseable jobs returned by any source' } }];
}
return out.map((row) => ({ json: row }));

// One INSERT per 75 rows, with ON CONFLICT DO NOTHING so re-running the
// workflow is safe (idempotency lives in the database, not in the code).
const items = $input.all().map((i) => i.json).filter((r) => r && r.fingerprint);
if (!items.length) return [{ json: { rows: 0, sql: 'SELECT 1;' } }];

const esc = (v) =>
  v === null || v === undefined || v === ''
    ? 'NULL'
    : "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";

const jsonb = (v) =>
  "'" + JSON.stringify(Array.isArray(v) ? v : []).replace(/'/g, "''") + "'::jsonb";

const stamp = (v) => {
  if (!v) return 'NULL';
  const d = new Date(v);
  return isNaN(d.getTime()) ? 'NULL' : "'" + d.toISOString() + "'::timestamptz";
};

const CHUNK = 75;
const chunks = [];
for (let i = 0; i < items.length; i += CHUNK) chunks.push(items.slice(i, i + CHUNK));

return chunks.map((rows, idx) => ({
  json: {
    chunk: idx + 1,
    rows: rows.length,
    sql:
      'INSERT INTO jobs (source, external_id, title, company, location, country, url, description, salary_text, tags, fingerprint, posted_at) VALUES ' +
      rows
        .map(
          (r) =>
            '(' +
            [
              esc(r.source),
              esc(r.external_id),
              esc(r.title),
              esc(r.company),
              esc(r.location),
              // undefined for rows that carry no location (alert emails) -> NULL
              esc(r.country),
              esc(r.url),
              esc(r.description),
              esc(r.salary_text),
              jsonb(r.tags),
              esc(r.fingerprint),
              stamp(r.posted_at),
            ].join(',') +
            ')'
        )
        .join(',') +
      ' ON CONFLICT (fingerprint) DO NOTHING RETURNING id;',
  },
}));

// Execution summary: the numbers you quote in the README / interview.
const parsed = $('Normalise jobs').all().filter((i) => i.json && i.json.fingerprint).length;
const offered = $('Build SQL chunks').all().reduce((n, i) => n + (i.json.rows || 0), 0);

let inserted = 0;
for (const i of $input.all()) {
  const j = i.json || {};
  if (Array.isArray(j)) inserted += j.length;
  else if (Array.isArray(j.rows)) inserted += j.rows.length;
  else if (j.id !== undefined) inserted += 1;
}

return [
  {
    json: {
      fetched: parsed,
      unique_in_batch: offered,
      new_rows: inserted,
      duplicates_skipped: Math.max(offered - inserted, 0),
      ran_at: new Date().toISOString(),
    },
  },
];
